from collections import deque

def shortest_edit_script(a: list[str], b: list[str]) -> list[tuple]:
    n = len(a)
    m = len(b)
    total_len = n + m

    # Use full DP for small enough tables.
    if (n + 1) * (m + 1) <= 300000:
        INF = total_len + 5
        dist = [[INF] * (m + 1) for _ in range(n + 1)]
        dist[n][m] = 0

        for i in range(n, -1, -1):
            for j in range(m, -1, -1):
                if i == n and j == m:
                    continue
                best = INF
                if i < n:
                    best = min(best, dist[i + 1][j] + 1)
                if j < m:
                    best = min(best, dist[i][j + 1] + 1)
                if i < n and j < m and a[i] == b[j]:
                    best = min(best, dist[i + 1][j + 1])
                dist[i][j] = best

        ans = []
        i = j = 0
        while i < n or j < m:
            cur = dist[i][j]

            if i < n and j < m and a[i] == b[j] and dist[i + 1][j + 1] == cur:
                ans.append(("=", i, j))
                i += 1
                j += 1
            elif i < n and dist[i + 1][j] + 1 == cur:
                ans.append(("-", i))
                i += 1
            else:
                ans.append(("+", j))
                j += 1

        return ans

    # Myers frontier version for large cases.
    A = a[::-1]
    B = b[::-1]
    end_k = n - m

    def snake(p: int, k: int) -> int:
        q = p - k
        while p < n and q < m and A[p] == B[q]:
            p += 1
            q += 1
        return p

    def distance_leq(i: int, j: int, budget: int) -> bool:
        if budget < 0:
            return False

        p = n - i
        q = m - j
        k = p - q

        # Distance from (i,j) in original corresponds to distance between
        # reversed prefixes A[:p], B[:q].
        max_d = min(budget, len(frontiers) - 1)
        for d in range(max_d + 1):
            if k < -d or k > d:
                continue
            arr = frontiers[d]
            if arr[k + d] >= p:
                return True
        return False

    frontiers: list[list[int]] = []

    v0 = [snake(0, 0)]
    frontiers.append(v0)

    D = None
    if end_k == 0 and v0[0] >= n:
        D = 0

    d = 1
    while D is None:
        prev = frontiers[d - 1]
        cur = [-1] * (2 * d + 1)

        for k in range(-d, d + 1):
            best = -1

            if -d + 1 <= k <= d - 1:
                best = max(best, prev[k + d - 1])

            if -d + 1 <= k - 1 <= d - 1:
                pp = prev[(k - 1) + d - 1]
                if pp >= 0 and pp < n:
                    best = max(best, pp + 1)

            if -d + 1 <= k + 1 <= d - 1:
                pp = prev[(k + 1) + d - 1]
                if pp >= 0:
                    qprev = pp - (k + 1)
                    if qprev < m:
                        best = max(best, pp)

            p = best
            if p >= 0:
                if p > n:
                    p = n
                q = p - k
                if q < 0:
                    p = max(0, k)
                    q = 0
                elif q > m:
                    p = min(n, m + k)
                    q = m

                while p < n and q < m and A[p] == B[q]:
                    p += 1
                    q += 1

                cur[k + d] = p

        frontiers.append(cur)

        if -d <= end_k <= d and cur[end_k + d] >= n:
            D = d
            break

        d += 1

    ans = []
    i = j = 0
    rem = D

    while i < n or j < m:
        if i < n and j < m and a[i] == b[j] and distance_leq(i + 1, j + 1, rem):
            ans.append(("=", i, j))
            i += 1
            j += 1
        elif i < n and distance_leq(i + 1, j, rem - 1):
            ans.append(("-", i))
            i += 1
            rem -= 1
        else:
            ans.append(("+", j))
            j += 1
            rem -= 1

    return ans
